 // Current production diagnosis: only the actual solver variables and its
 // first real proposal. No full-raw export, family grid, or second Solver.
 struct NarrowBlockV1{double*data;int ambient,tangent;std::size_t offset,gradient_offset;const ceres::Manifold*chart;};
